-- Count a vote and choose one player to remove only when there is a clear winning choice.
-- ballot-resolution: original MIT-licensed native educational port.
-- Generated by tools/ports/generate.py; edit the specification to preserve parity.
-- Input:
-- [candidate_count,voter_count,...candidate_ids,...eligible_voter_ids,...[voter_id,target_id]]
-- Output: [eliminated_id_or_minus_one]
-- Unique nonnegative IDs; -1 is an explicit skip. Reject ineligible voters/targets and duplicate
-- ballots. A plurality tie or skip win causes no elimination.
-- Precondition: finite, correctly shaped data; integer indices/counts/IDs.
-- See ../PORTS.md for examples, limits, and the shared test fixtures.

-- Count how many numbers are in this list.
local function port_length(a) return #a end
-- Read one number at a zero-based position; stop if that position does not exist.
local function port_get(a,i) assert(i>=0 and i==math.floor(i) and i<#a,"index"); return a[i+1] end
-- Replace a number at an existing position in the list.
local function port_put(a,i,v) port_get(a,i); a[i+1]=v end
-- Add one number to the end of the list.
local function port_push(a,v) a[#a+1]=v end

-- 1. Accept at most one vote from each eligible voter.
-- 2. Count votes for eligible candidates; minus one means skip.
-- 3. Find the largest vote count.
-- 4. A tie, no votes, or a winning skip vote removes nobody.
local function compute(data)
    local n = 0
    local voters = 0
    local counts = {}
    local i = 0
    local seen = {}
    local best = 0
    local winner = 0
    local tied = 0
    local voter = 0
    local target = 0
    local eligible = 0
    local j = 0
    local index = 0
    local count = 0
    n = port_get(data, 0)
    voters = port_get(data, 1)
    if ((n < 0) or (voters < 0)) then
        return {-(2)}
    end
    counts = {}
    i = 0
    while (i < (n + 1)) do
        port_push(counts, 0)
        i = i + 1
    end
    seen = {}
    i = ((2 + n) + voters)
    while (i < port_length(data)) do
        voter = port_get(data, i)
        target = port_get(data, (i + 1))
        eligible = 0
        j = 0
        while (j < voters) do
            if (port_get(data, ((2 + n) + j)) == voter) then
                eligible = 1
            end
            j = j + 1
        end
        j = 0
        while (j < port_length(seen)) do
            if (port_get(seen, j) == voter) then
                eligible = 0
            end
            j = j + 1
        end
        if (eligible == 0) then
            return {-(2)}
        end
        port_push(seen, voter)
        index = -(1)
        if (target == -(1)) then
            index = n
        end
        j = 0
        while (j < n) do
            if (port_get(data, (2 + j)) == target) then
                index = j
            end
            j = j + 1
        end
        if (index < 0) then
            return {-(2)}
        end
        port_put(counts, index, (port_get(counts, index) + 1))
        i = i + 2
    end
    best = 0
    winner = -(1)
    tied = 0
    i = 0
    while (i < (n + 1)) do
        count = port_get(counts, i)
        if (count > best) then
            best = count
            winner = i
            tied = 0
        else
            if (count == best) then
                tied = 1
            end
        end
        i = i + 1
    end
    if ((best == 0) or (tied == 1) or (winner == n)) then
        return {-(1)}
    end
    return {port_get(data, (2 + winner))}
end
return {compute=compute}
